mapper.update:
UPDATE public.nocode_date_trigger_state
SET armed = false, updater = #{actor}, update_time = clock_timestamp()
WHERE application_id = #{app}
AND armed = true

    AND resource_id NOT IN
    #{id}

UPDATE public.nocode_date_trigger_state
SET closed_date = GREATEST(closed_date, #{date}), update_time = clock_timestamp()
WHERE application_id = #{app}
AND resource_id = #{resource}

UPDATE public.nocode_date_trigger_state
SET last_scan_at = clock_timestamp(), last_scan_date = #{date}, last_trigger = #{trigger},
    last_error = #{error}, update_time = clock_timestamp()
WHERE application_id = #{app}
AND resource_id = #{resource}

UPDATE public.nocode_date_trigger_done
SET outcome = #{outcome}, target_count = #{targets}, done_at = clock_timestamp(),
    update_time = clock_timestamp()
WHERE application_id = #{app}
AND resource_id = #{resource}
AND business_date = #{date}
AND source_record_id = #{source}
AND outcome = 'RUNNING'

mapper.select:
SELECT source_record_id
FROM public.nocode_date_trigger_done
WHERE application_id = #{app}
AND resource_id = #{resource}
AND business_date = #{date}

mapper.delete:
DELETE FROM public.nocode_date_trigger_done
WHERE application_id = #{app}
AND resource_id = #{resource}
AND business_date = #{date}
AND outcome = 'FAILED'

mapper.select:
SELECT *
FROM public.nocode_date_trigger_done
WHERE application_id = #{app}
AND resource_id = #{resource}
AND business_date = #{date}
ORDER BY (outcome = 'FAILED') DESC, done_at DESC, id DESC
LIMIT #{limit}

SELECT outcome || ':' || count(*)
FROM public.nocode_date_trigger_done
WHERE application_id = #{app}
AND resource_id = #{resource}
AND business_date = #{date}
GROUP BY outcome
ORDER BY outcome
